// The planner. Every 15 minutes it reads the calendar, the sheets and the
// log, and writes down what should happen next: a confirmation to ask, a
// slot to offer, a recall to send, a no-show to count. It sends nothing
// itself - every message it decides on is a row in the log first, so a text
// that failed to send is never sent twice, and one that was sent is never
// forgotten.

const cfg = $('Set Clinic Settings').first().json;
const txt = $('Set Message Texts').first().json;

function rowsOf(name) {
  try {
    const rows = $(name).first().json.rows || [];
    return rows.filter((r) => r && typeof r === 'object' && Object.keys(r).length);
  } catch (e) {
    return [];
  }
}

const MIN = 60000;
const HOUR = 3600000;
const DAY = 86400000;
// Always Date.now(), never new Date() with no argument: one clock, read once.
const NOW = Date.now();
const STAMP = new Date(NOW).toISOString();

const num = (v, d) => {
  if (v === null || v === undefined || String(v).trim() === '') return d;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : d;
};
const yes = (v) => v === true || /^(true|yes|y|1|si|sì)$/i.test(String(v == null ? '' : v).trim());
const low = (v) => String(v == null ? '' : v).trim().toLowerCase();
const placeholder = (v) => !String(v || '').trim() || /^YOUR_/.test(String(v).trim());

const minNotice = num(cfg.min_notice_hours, 2) * HOUR;
const lateHours = num(cfg.late_cancel_hours, 24) * HOUR;
const depositAfter = num(cfg.deposit_after_no_shows, 2);
const lateCounts = yes(cfg.late_cancel_counts);
const twilioReady = !placeholder(cfg.twilio_from);

// --- time, in the clinic's own time zone -------------------------------------
// n8n runs in UTC on most servers. "Not before 8" means 8 at the clinic.

const TZ = String(cfg.timezone || 'UTC');
const LOCALE = String(cfg.locale || 'en-GB');
const partsFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', weekday: 'short', hourCycle: 'h23',
});
const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
function local(t) {
  const o = {};
  for (const p of partsFmt.formatToParts(new Date(t))) o[p.type] = p.value;
  return {
    date: `${o.year}-${o.month}-${o.day}`,
    hour: Number(o.hour) % 24,
    minute: Number(o.minute),
    weekday: WEEKDAYS.indexOf(String(o.weekday).toLowerCase().slice(0, 3)),
  };
}
const dayFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long' });
const timeFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: TZ, hour: '2-digit', minute: '2-digit' });
const dayLabel = (t) => dayFmt.format(new Date(t));
const timeLabel = (t) => timeFmt.format(new Date(t));
const iso = (t) => new Date(t).toISOString();
function money(v) {
  try {
    return new Intl.NumberFormat(LOCALE, { style: 'currency', currency: String(cfg.currency || 'EUR') }).format(v);
  } catch (e) {
    return `${Number(v).toFixed(2)} ${cfg.currency || ''}`.trim();
  }
}

function sendWindow(t) {
  const h = local(t).hour;
  return h >= num(cfg.send_from_hour, 8) && h < num(cfg.send_to_hour, 20);
}

// --- who is who ---------------------------------------------------------------

const normEmail = (s) => {
  const m = String(s || '').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  return m ? m[0] : '';
};
// Numbers become +<country><number>. The trunk 0 is dropped, as it is in
// London (07700 -> +1234567890), except in Italy, where it is part of the number
// (06 is Rome, and +39 06 is still Rome).
function normPhone(s) {
  let p = String(s || '').replace(/^\s*(whatsapp|sms|tel):/i, '').replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p && !p.startsWith('+')) {
    const cc = String(cfg.default_country_code || '').replace(/\D/g, '');
    if (!cc) return '';
    if (cc !== '39') p = p.replace(/^0/, '');
    p = `+${cc}${p}`;
  }
  const digits = p.replace(/\D/g, '');
  return digits.length >= 8 && digits.length <= 15 ? p : '';
}

const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const PHONE_RE = /(?:\+|00)?\d[\d\s().\/-]{6,}\d/g;
// A date is eight digits too. "2026-10-01" in a description is not a phone.
const DATE_LIKE = /^\s*(\d{4}[-/.]\d{1,2}[-/.]\d{1,2}|\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4})\s*$/;
const phonesIn = (text) => (String(text || '').match(PHONE_RE) || [])
  .filter((c) => !DATE_LIKE.test(c)).map(normPhone).filter(Boolean);

const words = (s) => ' ' + low(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').trim() + ' ';

const services = rowsOf('Aggregate Services').map((s) => ({
  name: String(s.service || s.name || '').trim(),
  price: num(s.price, 0),
  minutes: num(s.minutes, 0),
  recall_weeks: num(s.recall_weeks, 0),
})).filter((s) => s.name);
const serviceNamed = (name) => services.find((s) => low(s.name) === low(name)) || null;
// The longest service name found in the text: "Deep cleaning" beats "Cleaning".
function serviceIn(text) {
  const w = words(text);
  let best = null;
  for (const s of services) {
    if (w.includes(words(s.name)) && (!best || s.name.length > best.name.length)) best = s;
  }
  return best;
}

const clients = rowsOf('Aggregate Clients').map((c) => {
  const name = String(c.name || '').trim();
  const email = normEmail(c.email);
  const phone = normPhone(c.phone);
  return {
    name, email, phone,
    first_name: name.split(/\s+/)[0] || '',
    channel: low(c.channel),
    key: email || phone || low(name),
    last_visit: String(c.last_visit || ''),
    last_service: String(c.last_service || ''),
  };
}).filter((c) => c.key);

// A client is found by email, then by phone, then by a name written in the
// event title - but only when exactly one client has that name. Two Maria
// Bianchi and a title that says "Maria Bianchi" is a question for a person,
// not a text to whichever of them comes first.
function matchClient(emails, phones, title) {
  for (const e of emails) {
    const c = clients.find((x) => x.email && x.email === e);
    if (c) return c;
  }
  for (const p of phones) {
    const c = clients.find((x) => x.phone && x.phone === p);
    if (c) return c;
  }
  const t = words(title);
  const named = clients.filter((c) => c.name && words(c.name).trim() && t.includes(words(c.name)));
  const keys = new Set(named.map((c) => c.key));
  if (keys.size === 1) return named[0];
  if (keys.size > 1) return { ambiguous: true, name: named.map((c) => c.name).join(' / ') };
  if (emails[0] || phones[0]) {
    return { name: '', first_name: '', email: emails[0] || '', phone: phones[0] || '',
      channel: '', key: emails[0] || phones[0] };
  }
  return null;
}
// An empty contact matches nobody - not the first client with no phone.
function clientByContact(contact) {
  if (!contact) return null;
  return clients.find((c) => c.email === contact || c.phone === contact) || null;
}

function parseEvent(e) {
  const s = e.start && e.start.dateTime;
  const en = e.end && e.end.dateTime;
  if (!e.id || !s || !en || e.status === 'cancelled') return null;   // all-day: not an appointment
  const start = Date.parse(s);
  const end = Date.parse(en);
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return null;
  const title = String(e.summary || '');
  const description = String(e.description || '');
  const attendees = (Array.isArray(e.attendees) ? e.attendees : [])
    .filter((a) => a && a.email && !a.self && !a.organizer && !a.resource)
    .map((a) => normEmail(a.email)).filter(Boolean);
  const emails = attendees.concat((description.match(EMAIL_RE) || []).map(normEmail));
  const service = serviceIn(title) || serviceIn(description);
  const client = matchClient(emails, phonesIn(description), title);
  const marked = (!placeholder(cfg.no_show_color) && String(e.colorId || '') === String(cfg.no_show_color))
    || /\bno[\s-]?show\b/i.test(`${title} ${description}`);
  const refill = (description.match(/#refill:([A-Za-z0-9_@.+-]+)/) || [])[1] || '';
  return { id: String(e.id), start, end, title, service, client, noShow: marked, refill };
}

const events = {};
for (const e of rowsOf('Aggregate Events')) {
  const p = parseEvent(e);
  if (p) events[p.id] = p;
}

// Where a message to this person goes: their own choice first, then text,
// then email - and never down a channel they said STOP to.
function reach(person, opted) {
  if (!person) return null;
  const smsOk = twilioReady && person.phone && !opted[`sms:${person.phone}`];
  const mailOk = person.email && !opted[`email:${person.email}`];
  if (person.channel === 'email' && mailOk) return { channel: 'email', to: person.email };
  if (smsOk) return { channel: 'sms', to: person.phone };
  if (mailOk) return { channel: 'email', to: person.email };
  return null;
}

const fill = (template, vars) => String(template || '')
  .replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null ? m : String(vars[k])));
const baseVars = {
  business: cfg.business_name || '',
  link: cfg.booking_link || '',
  deposit_link: cfg.deposit_link || '',
};

// --- the log, read back into state ------------------------------------------
// The Log tab is the only thing this workflow writes to, and it only ever
// appends. Everything it knows - what was asked, confirmed, freed, offered,
// booked - is rebuilt from it here, the same way on every run.

function buildState(rows) {
  const S = { appts: {}, slots: {}, offers: [], opted: {}, recalls: {}, alerts: {},
    digests: {}, reports: {}, outbound: [], refills: [] };
  const appt = (id) => (S.appts[id] = S.appts[id] || { id, asked: {}, nudged: {}, confirmed: {} });
  for (const r of rows) {
    const ev = String(r.event || '');
    const id = String(r.appointment_id || '');
    const at = Date.parse(r.at) || 0;
    const start = String(r.start || '');
    const contact = String(r.contact || '');
    switch (ev) {
      case 'seen':
        Object.assign(appt(id), {
          start, end: String(r.end || ''), client: String(r.client || ''), contact,
          channel: String(r.channel || ''), service: String(r.service || ''),
          price: num(r.price, 0), seenAt: at, source: String(r.detail || ''),
        });
        break;
      case 'moved':
        Object.assign(appt(id), { start, end: String(r.end || '') });
        break;
      case 'asked':
      case 'nudged':
        appt(id)[ev][start] = at;
        S.outbound.push({ kind: 'confirm', ref: id, contact, at });
        break;
      case 'confirmed':
        appt(id).confirmed[start] = at;
        break;
      case 'cancelled':
      case 'late_cancel':
        Object.assign(appt(id), { cancelled: ev, cancelledAt: at });
        break;
      case 'no_show':
      case 'attended':
        Object.assign(appt(id), { outcome: ev, outcomeAt: at });
        break;
      case 'freed':
        S.slots[id] = { id, start: Date.parse(start), end: Date.parse(r.end), service: String(r.service || ''),
          price: num(r.price, 0), client: String(r.client || ''), freedAt: at, refills: [] };
        break;
      case 'offered':
        S.offers.push({ slot: String(r.slot_id || ''), waitlist: String(r.waitlist_id || ''), contact,
          channel: String(r.channel || ''), at, expires: Date.parse(r.expires) || at, declined: false,
          detail: String(r.detail || ''), service: String(r.service || ''), price: num(r.price, 0),
          start: Date.parse(r.start), end: Date.parse(r.end) });
        S.outbound.push({ kind: 'offer', ref: String(r.slot_id || ''), contact, at });
        break;
      case 'offer_declined':
      case 'offer_taken':
        for (const o of S.offers) {
          if (o.slot === String(r.slot_id || '') && o.contact === contact) o.declined = true;
        }
        break;
      case 'refilled': {
        const rec = { slot: String(r.slot_id || ''), waitlist: String(r.waitlist_id || ''), contact,
          at, price: num(r.price, 0), start: Date.parse(start) };
        S.refills.push(rec);
        if (S.slots[rec.slot]) S.slots[rec.slot].refills.push(rec);
        break;
      }
      case 'opt_out':
        S.opted[`${r.channel}:${contact}`] = true;
        break;
      case 'opt_in':
        delete S.opted[`${r.channel}:${contact}`];
        break;
      case 'recall_sent':
      case 'recall_reminded':
      case 'recall_declined':
      case 'recall_booked': {
        const k = String(r.client || '');
        (S.recalls[k] = S.recalls[k] || []).push({ ev, at, service: String(r.service || '') });
        if (ev === 'recall_sent' || ev === 'recall_reminded') {
          S.outbound.push({ kind: 'recall', ref: k, contact, at, service: String(r.service || '') });
        }
        break;
      }
      case 'alert':
        S.alerts[String(r.detail || '')] = at;
        break;
      case 'digest_sent':
        S.digests[String(r.detail || '')] = true;
        break;
      case 'report_sent':
        S.reports[String(r.detail || '')] = true;
        break;
      default:
        break;
    }
  }
  return S;
}

// No-shows in the last year, and late cancellations if the policy counts them.
function strikes(S, client) {
  if (!client) return 0;
  let n = 0;
  for (const a of Object.values(S.appts)) {
    if (a.client !== client) continue;
    if (NOW - Date.parse(a.start) > 365 * DAY) continue;
    if (a.outcome === 'no_show') n += 1;
    else if (lateCounts && a.cancelled === 'late_cancel') n += 1;
  }
  return n;
}

const out = [];
let seq = 0;
function emit(event, fields, msg) {
  const row = {
    log_id: `${NOW.toString(36)}-${++seq}`, at: STAMP, event,
    appointment_id: '', start: '', end: '', client: '', contact: '', channel: '', service: '',
    price: '', waitlist_id: '', slot_id: '', expires: '', detail: '',
    ...(fields || {}),
  };
  if (msg) {
    row.send_channel = msg.channel;
    row.send_to = msg.to;
    row.send_subject = msg.subject || '';
    row.send_text = msg.text;
  }
  out.push({ json: row });
  return row;
}
const toDesk = (subject, text) => ({ channel: 'email', to: cfg.front_desk_email, subject, text });

const S = buildState(rowsOf('Aggregate Log'));
const confirmBefore = num(cfg.confirm_hours, 48) * HOUR;
const nudgeBefore = num(cfg.nudge_hours, 24) * HOUR;
const lookAhead = num(cfg.look_ahead_days, 60) * DAY;
const canSend = sendWindow(NOW);
const today = local(NOW).date;

const personOf = (ev) => (ev.client && !ev.client.ambiguous ? ev.client : null);
const contactOf = (person) => reach(person, S.opted);
const apptFields = (ev, person, extra) => ({
  appointment_id: ev.id, start: iso(ev.start), end: iso(ev.end),
  client: person ? person.key : '', service: ev.service ? ev.service.name : '',
  price: ev.service ? ev.service.price : '', ...(extra || {}),
});
const varsFor = (ev, person) => ({
  ...baseVars,
  first_name: (person && person.first_name) || '',
  service: ev.service ? ev.service.name : 'appointment',
  day: dayLabel(ev.start), time: timeLabel(ev.start),
});
function message(kind, contact, vars) {
  const subject = fill(txt[`${kind}_subject`] || txt.subject_default || '{business}', vars);
  return { channel: contact.channel, to: contact.to, subject, text: fill(txt[kind], vars) };
}

// ---------------------------------------------------------------------------
// 1. What the calendar says, against what the log remembers
// ---------------------------------------------------------------------------

// A calendar that comes back empty is not a clinic whose clients all
// cancelled overnight. It is a wrong calendar ID, or a token that expired.
// When more than half the known appointments vanish at once, nobody is told
// their slot is gone and nothing goes to the waitlist: somebody is told the
// calendar looks wrong.
const upcomingKnown = Object.values(S.appts).filter((a) => a.seenAt && !a.cancelled
  && Date.parse(a.start) > NOW && Date.parse(a.start) < NOW + lookAhead - DAY);
const vanished = upcomingKnown.filter((a) => !events[a.id]);
const calendarLooksWrong = vanished.length >= 3 && vanished.length > upcomingKnown.length / 2;

if (calendarLooksWrong) {
  const key = `calendar-empty:${today}`;
  if (!S.alerts[key]) {
    emit('alert', { detail: key }, toDesk(
      `${cfg.business_name}: the calendar looks wrong`,
      `${vanished.length} of ${upcomingKnown.length} upcoming appointments are missing from the ` +
      `calendar this run. Nothing was cancelled and nobody was messaged.\n\n` +
      `Check the calendar ID in Set Clinic Settings and the Google Calendar credential.`));
  }
} else {
  for (const a of vanished) {
    const start = Date.parse(a.start);
    emit('cancelled', { appointment_id: a.id, start: a.start, end: a.end, client: a.client,
      service: a.service, price: a.price, detail: 'removed from the calendar' });
    a.cancelled = 'cancelled';
    if (start - NOW > minNotice) {
      emit('freed', { appointment_id: a.id, start: a.start, end: a.end, client: a.client,
        service: a.service, price: a.price });
      S.slots[a.id] = { id: a.id, start, end: Date.parse(a.end), service: a.service, price: a.price,
        client: a.client, freedAt: NOW, refills: [] };
    }
  }
}

// Recalls that turned into a booking: counted when the booking first appears.
function creditRecall(person, ev) {
  if (!person) return;
  const list = S.recalls[person.key] || [];
  const sent = list.filter((r) => r.ev === 'recall_sent' && NOW - r.at < 60 * DAY);
  if (!sent.length) return;
  const last = sent[sent.length - 1];
  if (list.some((r) => r.ev === 'recall_booked' && r.at >= last.at)) return;
  emit('recall_booked', apptFields(ev, person, { detail: last.service }));
  list.push({ ev: 'recall_booked', at: NOW, service: last.service });
}

for (const ev of Object.values(events)) {
  const person = personOf(ev);
  let a = S.appts[ev.id];
  if (!a) {
    if (ev.start <= NOW) continue;                     // first seen after it began: not ours to judge
    if (!ev.service && !person) continue;              // lunch, a meeting, a blocked hour
    const c = contactOf(person);
    emit('seen', apptFields(ev, person, {
      contact: c ? c.to : '', channel: c ? c.channel : '',
      detail: ev.refill ? 'waitlist' : '',
    }));
    a = S.appts[ev.id] = { id: ev.id, asked: {}, nudged: {}, confirmed: {}, start: iso(ev.start),
      end: iso(ev.end), client: person ? person.key : '', seenAt: NOW,
      price: ev.service ? ev.service.price : 0, service: ev.service ? ev.service.name : '' };
    if (ev.refill) {
      // Booked from the waitlist: the client said yes an hour ago.
      emit('confirmed', apptFields(ev, person, { detail: 'booked from the waitlist' }));
      a.confirmed[iso(ev.start)] = NOW;
    } else {
      creditRecall(person, ev);
    }
  } else if (Date.parse(a.start) !== ev.start && !a.cancelled) {
    // Moved. A confirmation was for the old time, so it is asked again.
    emit('moved', apptFields(ev, person, { detail: `was ${a.start}` }));
    a.start = iso(ev.start);
    a.end = iso(ev.end);
  }
}

// ---------------------------------------------------------------------------
// 2. What happened to the ones that are over
// ---------------------------------------------------------------------------
// Only appointments the log knew about: an appointment is never first seen
// after it started, so the first run does not decide that everyone in the
// last two days turned up.

const settleAfter = num(cfg.mark_no_show_within_hours, 24) * HOUR;
for (const ev of Object.values(events)) {
  const a = S.appts[ev.id];
  if (!a || !a.seenAt || a.cancelled || ev.end > NOW) continue;
  const fields = { appointment_id: ev.id, start: iso(ev.start), end: iso(ev.end), client: a.client,
    service: a.service, price: a.price };
  if (ev.noShow && a.outcome !== 'no_show') {
    emit('no_show', fields);
    a.outcome = 'no_show';
  } else if (!ev.noShow && !a.outcome && NOW - ev.end >= settleAfter) {
    emit('attended', fields);
    a.outcome = 'attended';
  }
}

// ---------------------------------------------------------------------------
// 3. Confirmations: a question, then a second one, then a person
// ---------------------------------------------------------------------------

for (const ev of Object.values(events)) {
  const a = S.appts[ev.id];
  if (!a || a.cancelled || ev.start <= NOW) continue;
  const key = iso(ev.start);
  if (a.confirmed[key]) continue;
  const lead = ev.start - NOW;
  if (lead <= minNotice || !canSend) continue;
  const person = personOf(ev);
  const c = contactOf(person);
  if (!c) continue;                                    // the daily list says who to call
  const vars = varsFor(ev, person);
  const risky = strikes(S, person.key) >= depositAfter && !placeholder(cfg.deposit_link);
  const fields = apptFields(ev, person, { contact: c.to, channel: c.channel });
  if (!a.asked[key] && lead <= confirmBefore) {
    emit('asked', { ...fields, detail: risky ? 'deposit' : '' },
      message(risky ? 'confirm_deposit' : 'confirm', c, vars));
    a.asked[key] = NOW;
  } else if (a.asked[key] && !a.nudged[key] && lead <= nudgeBefore && NOW - a.asked[key] >= 4 * HOUR) {
    emit('nudged', fields, message('nudge', c, vars));
    a.nudged[key] = NOW;
  }
}

// ---------------------------------------------------------------------------
// 4. Freed slots go to the waitlist, a few people at a time
// ---------------------------------------------------------------------------

const DAY_NAMES = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
function daysOf(text) {
  const s = low(text);
  if (!s || s === 'any' || s === 'all') return null;
  const set = new Set();
  for (const part of s.split(/[,;/\s]+/).filter(Boolean)) {
    if (/^weekdays?$/.test(part)) [1, 2, 3, 4, 5].forEach((d) => set.add(d));
    else if (/^weekends?$/.test(part)) [0, 6].forEach((d) => set.add(d));
    else if (part.includes('-')) {
      const [a, b] = part.split('-').map((x) => DAY_NAMES[x.slice(0, 3)]);
      if (a === undefined || b === undefined) continue;
      for (let d = a; ; d = (d + 1) % 7) { set.add(d); if (d === b) break; }
    } else if (DAY_NAMES[part.slice(0, 3)] !== undefined) set.add(DAY_NAMES[part.slice(0, 3)]);
  }
  return set.size ? set : null;
}
function minutesOf(text, fallback) {
  const m = String(text || '').trim().match(/^(\d{1,2})(?:[:.h](\d{2}))?/);
  return m ? Number(m[1]) * 60 + Number(m[2] || 0) : fallback;
}
function dateOnly(text) {
  const s = String(text || '').trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  if (m) {
    const [d, mo] = String(cfg.date_order) === 'MDY' ? [m[2], m[1]] : [m[1], m[2]];
    return `${m[3]}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  return '';
}

const waitlist = rowsOf('Aggregate Waitlist').map((w, i) => {
  const email = normEmail(w.email);
  const phone = normPhone(w.phone);
  const known = clientByContact(email) || clientByContact(phone);
  return {
    id: String(w.waitlist_id || email || phone || `row-${i + 2}`),
    name: String(w.name || (known && known.name) || '').trim(),
    email, phone,
    channel: low(w.channel) || (known ? known.channel : ''),
    key: known ? known.key : (email || phone),
    service: String(w.service || '').trim(),
    days: daysOf(w.days),
    from: minutesOf(w.from_time, 0),
    to: minutesOf(w.to_time, 24 * 60),
    until: dateOnly(w.until),
    added: Date.parse(w.added_on) || 0,
    active: !/^(no|removed|booked|done|inactive)$/.test(low(w.status)),
    order: i,
  };
}).filter((w) => w.active && (w.email || w.phone));

const refilledBy = (w) => S.refills.some((r) => r.waitlist === w.id && r.at >= w.added);
const openOffer = (contact) => S.offers.some((o) => o.contact === contact && !o.declined
  && o.expires > NOW && !(S.slots[o.slot] && S.slots[o.slot].refills.length));
const busyAt = (person, start, end) => Object.values(events).some((ev) => {
  const p = personOf(ev);
  const a = S.appts[ev.id];
  return p && person && p.key === person.key && !(a && a.cancelled) && ev.start < end && start < ev.end;
});
// Their own later appointment for the same thing: taking the earlier slot
// gives this one up, and the later one goes to the list in its turn.
function laterBooking(w, serviceName, start) {
  return Object.values(events).filter((ev) => {
    const p = personOf(ev);
    const a = S.appts[ev.id];
    return p && p.key === w.key && ev.start > start && !(a && a.cancelled)
      && ev.service && low(ev.service.name) === low(serviceName);
  }).sort((x, y) => x.start - y.start)[0] || null;
}

function fits(w, slot) {
  const name = w.service || slot.service;
  const svc = serviceNamed(name);
  const length = (slot.end - slot.start) / MIN;
  const minutes = svc && svc.minutes ? svc.minutes : length;
  if (minutes > length) return null;
  const L = local(slot.start);
  if (w.days && !w.days.has(L.weekday)) return null;
  const from = L.hour * 60 + L.minute;
  if (from < w.from || from + minutes > w.to) return null;
  if (w.until && L.date > w.until) return null;
  return { service: name, minutes, price: svc ? svc.price : slot.price };
}

const waves = num(cfg.offer_batch, 3);
const offerFor = num(cfg.offer_minutes, 45) * MIN;
const offeredNow = new Set();

for (const slot of Object.values(S.slots).sort((x, y) => x.start - y.start)) {
  if (slot.refills.length || slot.start - NOW <= minNotice || !canSend) continue;
  const mine = S.offers.filter((o) => o.slot === slot.id);
  if (mine.some((o) => !o.declined && o.expires > NOW)) continue;    // a wave is still out
  const tried = new Set(mine.map((o) => o.contact));

  const picks = [];
  for (const w of waitlist.slice().sort((x, y) => (x.added - y.added) || (x.order - y.order))) {
    if (picks.length >= waves) break;
    if (w.key === slot.client || refilledBy(w)) continue;
    const c = reach(w, S.opted);
    if (!c || tried.has(c.to) || offeredNow.has(c.to) || openOffer(c.to)) continue;
    if (strikes(S, w.key) >= depositAfter) continue;               // the waitlist is for people who come
    const fit = fits(w, slot);
    if (!fit) continue;
    const end = slot.start + fit.minutes * MIN;
    if (busyAt(w, slot.start, end)) continue;
    picks.push({ w, c, fit, end, later: laterBooking(w, fit.service, slot.start) });
  }

  const expires = Math.min(NOW + offerFor, slot.start - minNotice);
  for (const p of picks) {
    offeredNow.add(p.c.to);
    const vars = { ...baseVars, first_name: p.w.name.split(/\s+/)[0] || '', service: p.fit.service,
      day: dayLabel(slot.start), time: timeLabel(slot.start),
      old_day: p.later ? dayLabel(p.later.start) : '', old_time: p.later ? timeLabel(p.later.start) : '' };
    emit('offered', {
      slot_id: slot.id, waitlist_id: p.w.id, contact: p.c.to, channel: p.c.channel,
      start: iso(slot.start), end: iso(p.end), service: p.fit.service, price: p.fit.price,
      client: p.w.key, expires: iso(expires), detail: p.later ? `move:${p.later.id}` : '',
    }, message(p.later ? 'offer_move_up' : 'offer', p.c, vars));
    S.offers.push({ slot: slot.id, contact: p.c.to, at: NOW, expires, declined: false });
  }
}

// ---------------------------------------------------------------------------
// 5. The checks that look at this workflow's own work
// ---------------------------------------------------------------------------

for (const slot of Object.values(S.slots)) {
  if (slot.refills.length > 1) {
    const key = `double-booked:${slot.id}`;
    if (!S.alerts[key]) {
      emit('alert', { slot_id: slot.id, detail: key }, toDesk(
        `${cfg.business_name}: one slot, two bookings`,
        `The slot on ${dayLabel(slot.start)} at ${timeLabel(slot.start)} was accepted by ` +
        `${slot.refills.map((r) => r.contact).join(' and ')} at almost the same moment.\n\n` +
        `Both are in the calendar. Please call one of them and offer another time.`));
    }
  }
  for (const r of slot.refills) {
    const inCalendar = Object.values(events).some((ev) => ev.refill === slot.id);
    const key = `not-in-calendar:${slot.id}`;
    if (!inCalendar && NOW - r.at > 30 * MIN && slot.start > NOW && !S.alerts[key]) {
      emit('alert', { slot_id: slot.id, detail: key }, toDesk(
        `${cfg.business_name}: a waitlist booking is missing from the calendar`,
        `${r.contact} accepted the slot on ${dayLabel(slot.start)} at ${timeLabel(slot.start)} and ` +
        `was told it is booked, but the calendar has no event for it. Please add it by hand.`));
    }
  }
}

// ---------------------------------------------------------------------------
// 6. Recalls: the check-up that is due and not booked
// ---------------------------------------------------------------------------

const lastVisit = {};
const visit = (client, service, t) => {
  if (!client || !service || !Number.isFinite(t)) return;
  const k = `${client}|${low(service)}`;
  if (!lastVisit[k] || lastVisit[k].t < t) lastVisit[k] = { client, service, t };
};
for (const c of clients) visit(c.key, c.last_service, Date.parse(dateOnly(c.last_visit) || c.last_visit));
for (const a of Object.values(S.appts)) {
  if (a.outcome === 'attended') visit(a.client, a.service, Date.parse(a.start));
}
const hasFuture = (key) => Object.values(events).some((ev) => {
  const p = personOf(ev);
  const a = S.appts[ev.id];
  return p && p.key === key && ev.start > NOW && !(a && a.cancelled);
});

const sentToday = rowsOf('Aggregate Log').filter((r) => r.event === 'recall_sent'
  && local(Date.parse(r.at) || 0).date === today).length;
let budget = Math.max(0, num(cfg.recalls_per_day, 20) - sentToday);
const maxOverdue = num(cfg.max_overdue_weeks, 52) * 7 * DAY;
const remindAfter = num(cfg.recall_remind_days, 14) * DAY;

const due = [];
for (const v of Object.values(lastVisit)) {
  const svc = serviceNamed(v.service);
  if (!svc || !svc.recall_weeks) continue;
  const when = v.t + svc.recall_weeks * 7 * DAY;
  if (when > NOW || NOW - when > maxOverdue) continue;
  if (hasFuture(v.client)) continue;
  const person = clients.find((c) => c.key === v.client);
  const c = reach(person, S.opted);
  if (!c) continue;
  const history = (S.recalls[v.client] || []).filter((r) => r.at > v.t && low(r.service) === low(svc.name));
  if (history.some((r) => r.ev === 'recall_declined' || r.ev === 'recall_booked')) continue;
  const sent = history.filter((r) => r.ev === 'recall_sent');
  const reminded = history.some((r) => r.ev === 'recall_reminded');
  due.push({ v, svc, person, c, when, sent: sent.length ? sent[sent.length - 1].at : 0, reminded });
}
// Most recently due first: somebody three weeks overdue still means to come,
// somebody three years overdue has found another dentist.
due.sort((x, y) => y.when - x.when);
if (canSend) {
  for (const d of due) {
    const fields = { client: d.v.client, contact: d.c.to, channel: d.c.channel, service: d.svc.name,
      price: d.svc.price, detail: iso(d.v.t) };
    const vars = { ...baseVars, first_name: d.person.first_name, service: d.svc.name,
      last_visit: dayLabel(d.v.t) };
    if (!d.sent) {
      if (budget <= 0) continue;
      budget -= 1;
      emit('recall_sent', fields, message('recall', d.c, vars));
    } else if (!d.reminded && NOW - d.sent >= remindAfter) {
      emit('recall_reminded', fields, message('recall_reminder', d.c, vars));
    }
  }
}

// ---------------------------------------------------------------------------
// 7. The front desk's list for tomorrow, once a day
// ---------------------------------------------------------------------------

const L = local(NOW);
if (L.hour >= num(cfg.digest_hour, 17) && !S.digests[today]) {
  const horizon = NOW + 36 * HOUR;
  const call = [];
  const unreachable = [];
  const deposit = [];
  for (const ev of Object.values(events).sort((x, y) => x.start - y.start)) {
    const a = S.appts[ev.id];
    if (!a || a.cancelled || ev.start <= NOW) continue;
    const person = personOf(ev);
    const when = `${dayLabel(ev.start)} ${timeLabel(ev.start)}`;
    const who = person ? (person.name || person.email || person.phone) : (ev.client ? ev.client.name : ev.title);
    if (ev.start < horizon && !a.confirmed[iso(ev.start)]) {
      if (!contactOf(person)) {
        unreachable.push(`- ${when}  ${who}${ev.client && ev.client.ambiguous ? '  (more than one client has this name)' : ''}`);
      } else if (a.asked[iso(ev.start)]) {
        call.push(`- ${when}  ${who}  ${person.phone || person.email}`);
      }
    }
    if (person && ev.start < NOW + 7 * DAY && strikes(S, person.key) >= depositAfter) {
      deposit.push(`- ${when}  ${who}: ${strikes(S, person.key)} no-shows this year`);
    }
  }
  const free = Object.values(S.slots).filter((s) => !s.refills.length && s.start > NOW
    && s.start < NOW + 7 * DAY).sort((x, y) => x.start - y.start)
    .map((s) => `- ${dayLabel(s.start)} ${timeLabel(s.start)}  ${s.service || ''}  ` +
      `(${S.offers.filter((o) => o.slot === s.id).length} offered so far)`);

  const parts = [];
  if (call.length) parts.push(`Not confirmed yet - please call:\n${call.join('\n')}`);
  if (unreachable.length) parts.push(`No phone or email we can use:\n${unreachable.join('\n')}`);
  if (deposit.length) parts.push(`Repeat no-shows booked this week - deposit asked:\n${deposit.join('\n')}`);
  if (free.length) parts.push(`Free slots still on offer:\n${free.join('\n')}`);
  if (parts.length) {
    emit('digest_sent', { detail: today }, toDesk(
      `${cfg.business_name}: tomorrow's list`, parts.join('\n\n')));
  }
}

// ---------------------------------------------------------------------------
// 8. Monday: what it was worth
// ---------------------------------------------------------------------------

if (L.weekday === num(cfg.report_weekday, 1) && L.hour >= num(cfg.report_hour, 8)
    && !S.reports[today] && !placeholder(cfg.owner_email)) {
  const from = NOW - 7 * DAY;
  const inWeek = (t) => t >= from && t < NOW;
  const all = Object.values(S.appts);
  const attended = all.filter((a) => a.outcome === 'attended' && inWeek(Date.parse(a.start)));
  const noShows = all.filter((a) => a.outcome === 'no_show' && inWeek(Date.parse(a.start)));
  const asked = all.filter((a) => Object.values(a.asked).some(inWeek));
  const confirmed = asked.filter((a) => Object.keys(a.confirmed).length);
  const cancelled = all.filter((a) => a.cancelled && inWeek(a.cancelledAt || 0));
  const late = cancelled.filter((a) => a.cancelled === 'late_cancel');
  const freed = Object.values(S.slots).filter((s) => inWeek(s.freedAt));
  const refills = S.refills.filter((r) => inWeek(r.at));
  const recallsSent = Object.values(S.recalls).flat().filter((r) => r.ev === 'recall_sent' && inWeek(r.at));
  const recallBooked = rowsOf('Aggregate Log').concat(out.map((o) => o.json))
    .filter((r) => r.event === 'recall_booked' && inWeek(Date.parse(r.at) || 0));
  const sum = (list) => list.reduce((s, x) => s + num(x.price, 0), 0);
  const refilledValue = sum(refills);
  const recallValue = sum(recallBooked);
  const pct = asked.length ? Math.round((confirmed.length / asked.length) * 100) : 0;

  const lines = [
    `Recovered this week: ${money(refilledValue + recallValue)}`,
    '',
    `  ${refills.length} cancelled slot(s) refilled from the waitlist   ${money(refilledValue)}`,
    `  ${recallBooked.length} booking(s) from recalls                  ${money(recallValue)}`,
    '',
    `Appointments attended: ${attended.length}`,
    `Confirmations asked:   ${asked.length}, confirmed ${confirmed.length} (${pct}%)`,
    `Cancellations:         ${cancelled.length}, of which ${late.length} late`,
    `Slots freed:           ${freed.length}`,
    `No-shows:              ${noShows.length}, ${money(sum(noShows))} not earned`,
    `Recalls sent:          ${recallsSent.length}`,
  ];
  emit('report_sent', { detail: today }, {
    channel: 'email', to: cfg.owner_email,
    subject: `${cfg.business_name}: ${money(refilledValue + recallValue)} recovered this week`,
    text: lines.join('\n'),
  });
}

return out;

// The rows are in the log. Now, and only now, the messages go.
return $('Plan the Next Actions').all()
  .map((i) => i.json)
  .filter((r) => r.send_to && r.send_text)
  .map((r) => ({ json: { channel: r.send_channel, to: r.send_to, subject: r.send_subject, text: r.send_text } }));

// Who wrote, and whether a person did. Texts and emails arrive in two
// different shapes; from here on they are one.
//
// An out-of-office is not a reply, and the model is not asked whether it is
// one: RFC 3834 headers answer that, and they win. The quoted part of an
// email is cut off before anything reads it, because our own message is in
// there - "Reply YES to confirm" - and a reply that says "sorry, can't make
// it" above it would otherwise contain the word YES.
//
// A sender nobody knows gets nothing back. A number that answers every text
// is a number that can be used to send texts.

const cfg = $('Set Clinic Settings').first().json;

function rows(name) {
  try { return ($(name).first().json.rows || []).filter((r) => r && Object.keys(r).length); } catch (e) { return []; }
}
function items(name) {
  try { return $(name).all(); } catch (e) { return []; }
}

const normEmail = (s) => {
  const m = String(s || '').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  return m ? m[0] : '';
};
function normPhone(s) {
  let p = String(s || '').replace(/^\s*(whatsapp|sms|tel):/i, '').replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p && !p.startsWith('+')) {
    const cc = String(cfg.default_country_code || '').replace(/\D/g, '');
    if (!cc) return '';
    if (cc !== '39') p = p.replace(/^0/, '');
    p = `+${cc}${p}`;
  }
  const digits = p.replace(/\D/g, '');
  return digits.length >= 8 && digits.length <= 15 ? p : '';
}

const known = new Set();
for (const r of rows('Aggregate Clients').concat(rows('Aggregate Waitlist'))) {
  if (normEmail(r.email)) known.add(normEmail(r.email));
  if (normPhone(r.phone)) known.add(normPhone(r.phone));
}
for (const r of rows('Aggregate Log')) if (r.contact) known.add(String(r.contact));

function automatic(meta) {
  const raw = meta.headers || {};
  const pairs = Array.isArray(raw) ? raw.map((h) => [h.name, h.value]) : Object.entries(raw);
  const headers = {};
  for (const [name, value] of pairs) {
    headers[String(name).toLowerCase()] = String(value == null ? '' : value).trim().toLowerCase();
  }
  const submitted = headers['auto-submitted'] || '';
  if (submitted && submitted !== 'no') return true;
  if (headers['x-autoreply'] || headers['x-autorespond'] || headers['x-auto-response-suppress']) return true;
  if (['bulk', 'auto_reply', 'list', 'junk'].includes(headers.precedence || '')) return true;
  const subject = String(meta.subject || '').toLowerCase().replace(/^((re|fwd?|aw|sv|r|rif)\s*:\s*)+/g, '').trim();
  return /^(auto(matic)?[ -]?(reply|response|answer)|autoreply|out of (the )?office|ooo\b|absence|risposta automatica|undeliverable|delivery status notification)/.test(subject);
}

// What the person wrote above what they were replying to.
function fresh(text) {
  const out = [];
  for (const line of String(text || '').replace(/\r\n/g, '\n').split('\n')) {
    if (/^\s*>/.test(line)) break;
    if (/^\s*-{2,}\s*(original message|messaggio originale)/i.test(line)) break;
    if (/^\s*(on|il|el|le|am) .+(wrote|ha scritto|escribió|a écrit|schrieb):?\s*$/i.test(line)) break;
    if (/^\s*from:\s/i.test(line) && out.length) break;
    out.push(line);
  }
  return out.join('\n').trim().slice(0, 1000);
}

// Twilio's own opt-out words. Twilio has already stopped texting this number
// by the time we see the message, whatever we do - and CANCEL is one of them,
// which is why the texts say "reply NO", never "reply CANCEL".
const CARRIER_STOP = ['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit', 'revoke', 'optout'];
const CARRIER_START = ['start', 'unstop'];
const YES = /^(yes|y|yeah|yep|ok|okay|confirm|confirmed|c|si|sì|sí|oui|ja|1|👍)$/;
const NO = /^(no|n|nope|non|nein|2)$/;

function keyword(text, channel) {
  const w = String(text || '').trim().toLowerCase().replace(/[.!,;:\s]+$/g, '').replace(/^[\s"']+/, '');
  if (channel === 'sms' && CARRIER_STOP.includes(w)) return w === 'cancel' ? 'stop_cancel' : 'stop';
  if (channel === 'sms' && CARRIER_START.includes(w)) return 'opt_in';
  if (channel === 'email' && /^(stop|unsubscribe|disiscrivimi)$/.test(w)) return 'stop';
  // "Yes please!", "no thanks": the courtesy is not the answer.
  const core = w.replace(/[\s,!.]+(please|thanks|thank you|thx|grazie|gracias|merci|danke)$/, '');
  if (YES.test(core)) return 'yes';
  if (NO.test(core)) return 'no';
  return '';
}

const pick = (...vals) => vals.find((v) => typeof v === 'string' && v.trim() !== '') || '';
const out = [];

for (const it of items('When a Text Arrives')) {
  const j = it.json || {};
  const inner = j.body && typeof j.body === 'object' ? j.body : {};
  const data = j.data && typeof j.data === 'object' ? j.data : {};
  const contact = normPhone(pick(j.From, inner.From, data.from, j.from));
  const text = pick(j.Body, inner.Body, data.body, typeof j.body === 'string' ? j.body : '').trim();
  if (!contact || !text || !known.has(contact)) continue;
  out.push({ json: { channel: 'sms', contact, text: text.slice(0, 1000), subject: '',
    keyword: keyword(text, 'sms'), message_id: pick(j.MessageSid, inner.MessageSid, data.messageSid) } });
}

for (const it of items('When an Email Arrives')) {
  const j = it.json || {};
  const from = j.from && typeof j.from === 'object'
    ? (j.from.value && j.from.value[0] && j.from.value[0].address) || j.from.text : j.from;
  const contact = normEmail(from);
  if (!contact || !known.has(contact) || automatic(j)) continue;
  const text = fresh(j.text || j.textPlain || j.snippet || '');
  if (!text) continue;
  out.push({ json: { channel: 'email', contact, text, subject: String(j.subject || ''),
    keyword: keyword(text.split('\n')[0], 'email'), message_id: String(j.id || j.messageId || '') } });
}

return out;

// The reply, acted on. "YES" means whatever we asked this person last: to
// confirm an appointment, to take a slot, to come back for a check-up. So
// the log is read for the last thing we sent them, and the answer is
// applied to that.
//
// The model reads free text - "sorry, the kids are sick" - and has to quote
// the words it read the intent from. A quote that is not in the message is a
// guess, and a guess does not cancel anybody's appointment: it goes to the
// front desk as a question.
//
// Taking a slot is checked against the calendar read at the start of this
// run, not the log alone. The slot was freed an hour ago and the online
// booking page may have sold it since.

const cfg = $('Set Clinic Settings').first().json;
const txt = $('Set Message Texts').first().json;

function rowsOf(name) {
  try {
    const rows = $(name).first().json.rows || [];
    return rows.filter((r) => r && typeof r === 'object' && Object.keys(r).length);
  } catch (e) {
    return [];
  }
}

const MIN = 60000;
const HOUR = 3600000;
const DAY = 86400000;
// Always Date.now(), never new Date() with no argument: one clock, read once.
const NOW = Date.now();
const STAMP = new Date(NOW).toISOString();

const num = (v, d) => {
  if (v === null || v === undefined || String(v).trim() === '') return d;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : d;
};
const yes = (v) => v === true || /^(true|yes|y|1|si|sì)$/i.test(String(v == null ? '' : v).trim());
const low = (v) => String(v == null ? '' : v).trim().toLowerCase();
const placeholder = (v) => !String(v || '').trim() || /^YOUR_/.test(String(v).trim());

const minNotice = num(cfg.min_notice_hours, 2) * HOUR;
const lateHours = num(cfg.late_cancel_hours, 24) * HOUR;
const depositAfter = num(cfg.deposit_after_no_shows, 2);
const lateCounts = yes(cfg.late_cancel_counts);
const twilioReady = !placeholder(cfg.twilio_from);

// --- time, in the clinic's own time zone -------------------------------------
// n8n runs in UTC on most servers. "Not before 8" means 8 at the clinic.

const TZ = String(cfg.timezone || 'UTC');
const LOCALE = String(cfg.locale || 'en-GB');
const partsFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', weekday: 'short', hourCycle: 'h23',
});
const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
function local(t) {
  const o = {};
  for (const p of partsFmt.formatToParts(new Date(t))) o[p.type] = p.value;
  return {
    date: `${o.year}-${o.month}-${o.day}`,
    hour: Number(o.hour) % 24,
    minute: Number(o.minute),
    weekday: WEEKDAYS.indexOf(String(o.weekday).toLowerCase().slice(0, 3)),
  };
}
const dayFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long' });
const timeFmt = new Intl.DateTimeFormat(LOCALE, { timeZone: TZ, hour: '2-digit', minute: '2-digit' });
const dayLabel = (t) => dayFmt.format(new Date(t));
const timeLabel = (t) => timeFmt.format(new Date(t));
const iso = (t) => new Date(t).toISOString();
function money(v) {
  try {
    return new Intl.NumberFormat(LOCALE, { style: 'currency', currency: String(cfg.currency || 'EUR') }).format(v);
  } catch (e) {
    return `${Number(v).toFixed(2)} ${cfg.currency || ''}`.trim();
  }
}

function sendWindow(t) {
  const h = local(t).hour;
  return h >= num(cfg.send_from_hour, 8) && h < num(cfg.send_to_hour, 20);
}

// --- who is who ---------------------------------------------------------------

const normEmail = (s) => {
  const m = String(s || '').toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  return m ? m[0] : '';
};
// Numbers become +<country><number>. The trunk 0 is dropped, as it is in
// London (07700 -> +1234567890), except in Italy, where it is part of the number
// (06 is Rome, and +39 06 is still Rome).
function normPhone(s) {
  let p = String(s || '').replace(/^\s*(whatsapp|sms|tel):/i, '').replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p && !p.startsWith('+')) {
    const cc = String(cfg.default_country_code || '').replace(/\D/g, '');
    if (!cc) return '';
    if (cc !== '39') p = p.replace(/^0/, '');
    p = `+${cc}${p}`;
  }
  const digits = p.replace(/\D/g, '');
  return digits.length >= 8 && digits.length <= 15 ? p : '';
}

const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const PHONE_RE = /(?:\+|00)?\d[\d\s().\/-]{6,}\d/g;
// A date is eight digits too. "2026-10-01" in a description is not a phone.
const DATE_LIKE = /^\s*(\d{4}[-/.]\d{1,2}[-/.]\d{1,2}|\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4})\s*$/;
const phonesIn = (text) => (String(text || '').match(PHONE_RE) || [])
  .filter((c) => !DATE_LIKE.test(c)).map(normPhone).filter(Boolean);

const words = (s) => ' ' + low(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').trim() + ' ';

const services = rowsOf('Aggregate Services').map((s) => ({
  name: String(s.service || s.name || '').trim(),
  price: num(s.price, 0),
  minutes: num(s.minutes, 0),
  recall_weeks: num(s.recall_weeks, 0),
})).filter((s) => s.name);
const serviceNamed = (name) => services.find((s) => low(s.name) === low(name)) || null;
// The longest service name found in the text: "Deep cleaning" beats "Cleaning".
function serviceIn(text) {
  const w = words(text);
  let best = null;
  for (const s of services) {
    if (w.includes(words(s.name)) && (!best || s.name.length > best.name.length)) best = s;
  }
  return best;
}

const clients = rowsOf('Aggregate Clients').map((c) => {
  const name = String(c.name || '').trim();
  const email = normEmail(c.email);
  const phone = normPhone(c.phone);
  return {
    name, email, phone,
    first_name: name.split(/\s+/)[0] || '',
    channel: low(c.channel),
    key: email || phone || low(name),
    last_visit: String(c.last_visit || ''),
    last_service: String(c.last_service || ''),
  };
}).filter((c) => c.key);

// A client is found by email, then by phone, then by a name written in the
// event title - but only when exactly one client has that name. Two Maria
// Bianchi and a title that says "Maria Bianchi" is a question for a person,
// not a text to whichever of them comes first.
function matchClient(emails, phones, title) {
  for (const e of emails) {
    const c = clients.find((x) => x.email && x.email === e);
    if (c) return c;
  }
  for (const p of phones) {
    const c = clients.find((x) => x.phone && x.phone === p);
    if (c) return c;
  }
  const t = words(title);
  const named = clients.filter((c) => c.name && words(c.name).trim() && t.includes(words(c.name)));
  const keys = new Set(named.map((c) => c.key));
  if (keys.size === 1) return named[0];
  if (keys.size > 1) return { ambiguous: true, name: named.map((c) => c.name).join(' / ') };
  if (emails[0] || phones[0]) {
    return { name: '', first_name: '', email: emails[0] || '', phone: phones[0] || '',
      channel: '', key: emails[0] || phones[0] };
  }
  return null;
}
// An empty contact matches nobody - not the first client with no phone.
function clientByContact(contact) {
  if (!contact) return null;
  return clients.find((c) => c.email === contact || c.phone === contact) || null;
}

function parseEvent(e) {
  const s = e.start && e.start.dateTime;
  const en = e.end && e.end.dateTime;
  if (!e.id || !s || !en || e.status === 'cancelled') return null;   // all-day: not an appointment
  const start = Date.parse(s);
  const end = Date.parse(en);
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return null;
  const title = String(e.summary || '');
  const description = String(e.description || '');
  const attendees = (Array.isArray(e.attendees) ? e.attendees : [])
    .filter((a) => a && a.email && !a.self && !a.organizer && !a.resource)
    .map((a) => normEmail(a.email)).filter(Boolean);
  const emails = attendees.concat((description.match(EMAIL_RE) || []).map(normEmail));
  const service = serviceIn(title) || serviceIn(description);
  const client = matchClient(emails, phonesIn(description), title);
  const marked = (!placeholder(cfg.no_show_color) && String(e.colorId || '') === String(cfg.no_show_color))
    || /\bno[\s-]?show\b/i.test(`${title} ${description}`);
  const refill = (description.match(/#refill:([A-Za-z0-9_@.+-]+)/) || [])[1] || '';
  return { id: String(e.id), start, end, title, service, client, noShow: marked, refill };
}

const events = {};
for (const e of rowsOf('Aggregate Events')) {
  const p = parseEvent(e);
  if (p) events[p.id] = p;
}

// Where a message to this person goes: their own choice first, then text,
// then email - and never down a channel they said STOP to.
function reach(person, opted) {
  if (!person) return null;
  const smsOk = twilioReady && person.phone && !opted[`sms:${person.phone}`];
  const mailOk = person.email && !opted[`email:${person.email}`];
  if (person.channel === 'email' && mailOk) return { channel: 'email', to: person.email };
  if (smsOk) return { channel: 'sms', to: person.phone };
  if (mailOk) return { channel: 'email', to: person.email };
  return null;
}

const fill = (template, vars) => String(template || '')
  .replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null ? m : String(vars[k])));
const baseVars = {
  business: cfg.business_name || '',
  link: cfg.booking_link || '',
  deposit_link: cfg.deposit_link || '',
};

// --- the log, read back into state ------------------------------------------
// The Log tab is the only thing this workflow writes to, and it only ever
// appends. Everything it knows - what was asked, confirmed, freed, offered,
// booked - is rebuilt from it here, the same way on every run.

function buildState(rows) {
  const S = { appts: {}, slots: {}, offers: [], opted: {}, recalls: {}, alerts: {},
    digests: {}, reports: {}, outbound: [], refills: [] };
  const appt = (id) => (S.appts[id] = S.appts[id] || { id, asked: {}, nudged: {}, confirmed: {} });
  for (const r of rows) {
    const ev = String(r.event || '');
    const id = String(r.appointment_id || '');
    const at = Date.parse(r.at) || 0;
    const start = String(r.start || '');
    const contact = String(r.contact || '');
    switch (ev) {
      case 'seen':
        Object.assign(appt(id), {
          start, end: String(r.end || ''), client: String(r.client || ''), contact,
          channel: String(r.channel || ''), service: String(r.service || ''),
          price: num(r.price, 0), seenAt: at, source: String(r.detail || ''),
        });
        break;
      case 'moved':
        Object.assign(appt(id), { start, end: String(r.end || '') });
        break;
      case 'asked':
      case 'nudged':
        appt(id)[ev][start] = at;
        S.outbound.push({ kind: 'confirm', ref: id, contact, at });
        break;
      case 'confirmed':
        appt(id).confirmed[start] = at;
        break;
      case 'cancelled':
      case 'late_cancel':
        Object.assign(appt(id), { cancelled: ev, cancelledAt: at });
        break;
      case 'no_show':
      case 'attended':
        Object.assign(appt(id), { outcome: ev, outcomeAt: at });
        break;
      case 'freed':
        S.slots[id] = { id, start: Date.parse(start), end: Date.parse(r.end), service: String(r.service || ''),
          price: num(r.price, 0), client: String(r.client || ''), freedAt: at, refills: [] };
        break;
      case 'offered':
        S.offers.push({ slot: String(r.slot_id || ''), waitlist: String(r.waitlist_id || ''), contact,
          channel: String(r.channel || ''), at, expires: Date.parse(r.expires) || at, declined: false,
          detail: String(r.detail || ''), service: String(r.service || ''), price: num(r.price, 0),
          start: Date.parse(r.start), end: Date.parse(r.end) });
        S.outbound.push({ kind: 'offer', ref: String(r.slot_id || ''), contact, at });
        break;
      case 'offer_declined':
      case 'offer_taken':
        for (const o of S.offers) {
          if (o.slot === String(r.slot_id || '') && o.contact === contact) o.declined = true;
        }
        break;
      case 'refilled': {
        const rec = { slot: String(r.slot_id || ''), waitlist: String(r.waitlist_id || ''), contact,
          at, price: num(r.price, 0), start: Date.parse(start) };
        S.refills.push(rec);
        if (S.slots[rec.slot]) S.slots[rec.slot].refills.push(rec);
        break;
      }
      case 'opt_out':
        S.opted[`${r.channel}:${contact}`] = true;
        break;
      case 'opt_in':
        delete S.opted[`${r.channel}:${contact}`];
        break;
      case 'recall_sent':
      case 'recall_reminded':
      case 'recall_declined':
      case 'recall_booked': {
        const k = String(r.client || '');
        (S.recalls[k] = S.recalls[k] || []).push({ ev, at, service: String(r.service || '') });
        if (ev === 'recall_sent' || ev === 'recall_reminded') {
          S.outbound.push({ kind: 'recall', ref: k, contact, at, service: String(r.service || '') });
        }
        break;
      }
      case 'alert':
        S.alerts[String(r.detail || '')] = at;
        break;
      case 'digest_sent':
        S.digests[String(r.detail || '')] = true;
        break;
      case 'report_sent':
        S.reports[String(r.detail || '')] = true;
        break;
      default:
        break;
    }
  }
  return S;
}

// No-shows in the last year, and late cancellations if the policy counts them.
function strikes(S, client) {
  if (!client) return 0;
  let n = 0;
  for (const a of Object.values(S.appts)) {
    if (a.client !== client) continue;
    if (NOW - Date.parse(a.start) > 365 * DAY) continue;
    if (a.outcome === 'no_show') n += 1;
    else if (lateCounts && a.cancelled === 'late_cancel') n += 1;
  }
  return n;
}

const out = [];
let seq = 0;
function emit(event, fields, msg) {
  const row = {
    log_id: `${NOW.toString(36)}-${++seq}`, at: STAMP, event,
    appointment_id: '', start: '', end: '', client: '', contact: '', channel: '', service: '',
    price: '', waitlist_id: '', slot_id: '', expires: '', detail: '',
    ...(fields || {}),
  };
  if (msg) {
    row.send_channel = msg.channel;
    row.send_to = msg.to;
    row.send_subject = msg.subject || '';
    row.send_text = msg.text;
  }
  out.push({ json: row });
  return row;
}
const toDesk = (subject, text) => ({ channel: 'email', to: cfg.front_desk_email, subject, text });

const S = buildState(rowsOf('Aggregate Log'));
const replies = $('Read the Reply').all().map((i) => i.json);
const read = $input.all().map((i) => i.json || {});
const INTENTS = ['yes', 'no', 'reschedule', 'stop', 'question', 'other'];
const squash = (s) => low(s).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

function intentOf(r, ai) {
  if (r.keyword) return r.keyword;
  const got = (ai && (ai.output || ai)) || {};
  const intent = low(got.intent);
  if (!INTENTS.includes(intent)) return 'other';
  const evidence = squash(got.evidence);
  if (!evidence || !squash(r.text).includes(evidence)) return 'other';
  return intent;
}

// The last thing we sent to this contact, and still open.
function contextOf(contact) {
  const mine = S.outbound.filter((o) => o.contact === contact).sort((a, b) => b.at - a.at);
  for (const o of mine) {
    if (o.kind === 'offer') {
      const offer = S.offers.filter((x) => x.slot === o.ref && x.contact === contact).pop();
      if (offer && !offer.declined && offer.start > NOW) return { kind: 'offer', offer };
    }
    if (o.kind === 'confirm') {
      const a = S.appts[o.ref];
      if (a && Date.parse(a.start) > NOW) return { kind: 'confirm', appt: a };
    }
    if (o.kind === 'recall' && NOW - o.at < 45 * DAY) return { kind: 'recall', recall: o };
  }
  return { kind: 'none' };
}

function nameOf(contact) {
  const c = clientByContact(contact);
  if (c) return c.name;
  const w = rowsOf('Aggregate Waitlist').find((x) => normEmail(x.email) === contact || normPhone(x.phone) === contact);
  return (w && w.name) || contact;
}
const replyTo = (r, kind, vars) => ({
  channel: r.channel, to: r.contact,
  subject: fill(txt[`${kind}_subject`] || txt.subject_default || '{business}', vars),
  text: fill(txt[kind], vars),
});
function forward(r, why) {
  emit('forwarded', { contact: r.contact, channel: r.channel, detail: why },
    toDesk(`${cfg.business_name}: ${nameOf(r.contact)} wrote`,
      `${why}\n\nFrom: ${nameOf(r.contact)} (${r.contact}, by ${r.channel === 'sms' ? 'text' : 'email'})\n\n` +
      `"${r.text}"`));
}

// Cancel an appointment we know: logged, taken out of the calendar, and
// offered to the waitlist if there is time to fill it.
function cancel(a, why, late) {
  const start = Date.parse(a.start);
  const kind = late && start - NOW < lateHours ? 'late_cancel' : 'cancelled';
  const fields = { appointment_id: a.id, start: a.start, end: a.end, client: a.client,
    service: a.service, price: a.price };
  const row = emit(kind, { ...fields, detail: why });
  row.action = 'delete';
  row.event_id = a.id;
  a.cancelled = kind;
  if (start - NOW > minNotice) {
    emit('freed', fields);
    S.slots[a.id] = { id: a.id, start, end: Date.parse(a.end), service: a.service, price: a.price,
      client: a.client, freedAt: NOW, refills: [] };
  }
  return kind;
}

replies.forEach((r, i) => {
  const intent = intentOf(r, read[i]);
  const ctx = contextOf(r.contact);
  const person = clientByContact(r.contact);
  const vars = { ...baseVars, first_name: person ? person.first_name : (nameOf(r.contact).split(/\s+/)[0] || '') };

  if (intent === 'opt_in') {
    emit('opt_in', { contact: r.contact, channel: r.channel });
    delete S.opted[`${r.channel}:${r.contact}`];
    return;
  }
  if (intent === 'stop' || intent === 'stop_cancel') {
    // Twilio answers STOP itself; an email STOP gets one line back.
    emit('opt_out', { contact: r.contact, channel: r.channel, client: person ? person.key : '' },
      r.channel === 'email' ? replyTo(r, 'opted_out', vars) : null);
    S.opted[`${r.channel}:${r.contact}`] = true;
    if (intent === 'stop_cancel' && ctx.kind === 'confirm') {
      // They wrote CANCEL. They meant the appointment; the carrier heard an
      // opt-out. Both happen, and the confirmation goes by email if we can.
      const a = ctx.appt;
      const kind = cancel(a, 'replied CANCEL by text', true);
      const mail = person && person.email && !S.opted[`email:${person.email}`] ? person.email : '';
      const v = { ...vars, service: a.service || 'appointment', day: dayLabel(Date.parse(a.start)),
        time: timeLabel(Date.parse(a.start)) };
      if (mail) {
        emit('message', { contact: mail, channel: 'email', appointment_id: a.id, detail: kind },
          { channel: 'email', to: mail, subject: fill(txt.cancelled_subject || txt.subject_default, v),
            text: fill(txt.cancelled, v) });
      }
      forward(r, `Cancelled the ${v.day} ${v.time} appointment. Their number is now opted out of ` +
        `texts by the carrier, so they will not get text reminders until they reply START.`);
    }
    return;
  }

  if (ctx.kind === 'confirm') {
    const a = ctx.appt;
    const start = Date.parse(a.start);
    const v = { ...vars, service: a.service || 'appointment', day: dayLabel(start), time: timeLabel(start) };
    const fields = { appointment_id: a.id, start: a.start, end: a.end, client: a.client,
      contact: r.contact, channel: r.channel, service: a.service, price: a.price };
    if (a.cancelled) return forward(r, 'Replied about an appointment that is already cancelled.');
    if (intent === 'yes') {
      if (!a.confirmed[a.start]) emit('confirmed', fields, replyTo(r, 'confirmed', v));
      a.confirmed[a.start] = NOW;
      return;
    }
    if (intent === 'no' || intent === 'reschedule') {
      const kind = cancel(a, intent === 'no' ? 'client said no' : 'client asked for another time', true);
      emit('message', { ...fields, detail: kind }, replyTo(r, 'cancelled', v));
      if (intent === 'reschedule') forward(r, `Cancelled the ${v.day} ${v.time} ${v.service}. They would like another time.`);
      return;
    }
    return forward(r, `About the ${v.service} on ${v.day} at ${v.time}.`);
  }

  if (ctx.kind === 'offer') {
    const o = ctx.offer;
    const slot = S.slots[o.slot];
    const v = { ...vars, service: o.service || 'appointment', day: dayLabel(o.start), time: timeLabel(o.start) };
    const fields = { slot_id: o.slot, waitlist_id: o.waitlist, contact: r.contact, channel: r.channel,
      start: iso(o.start), end: iso(o.end), service: o.service, price: o.price };
    if (intent === 'no') {
      emit('offer_declined', fields);
      o.declined = true;
      return;
    }
    if (intent !== 'yes') return forward(r, `About the free slot on ${v.day} at ${v.time} we offered them.`);

    const moveId = (o.detail.match(/^move:(.+)$/) || [])[1] || '';
    const clash = Object.values(events).some((ev) => ev.id !== o.slot && ev.id !== moveId
      && !(S.appts[ev.id] && S.appts[ev.id].cancelled) && ev.start < o.end && o.start < ev.end);
    const gone = !slot || slot.refills.length || o.start - NOW < minNotice || clash;
    if (gone) {
      emit('offer_taken', { ...fields, detail: clash ? 'booked in the calendar meanwhile' : 'taken' },
        replyTo(r, 'taken', v));
      o.declined = true;
      return;
    }
    const w = rowsOf('Aggregate Waitlist').find((x) => String(x.waitlist_id || normEmail(x.email) || normPhone(x.phone)) === o.waitlist) || {};
    const name = String(w.name || nameOf(r.contact));
    const phone = normPhone(w.phone) || (person && person.phone) || (r.channel === 'sms' ? r.contact : '');
    const email = normEmail(w.email) || (person && person.email) || (r.channel === 'email' ? r.contact : '');
    const row = emit('refilled', { ...fields, client: person ? person.key : (email || phone) },
      replyTo(r, 'booked', v));
    Object.assign(row, {
      action: 'create',
      cal_summary: `${o.service} - ${name}`,
      cal_start: iso(o.start),
      cal_end: iso(o.end),
      cal_description: `Booked from the waitlist.\n${phone ? `Phone: ${phone}\n` : ''}${email ? `Email: ${email}\n` : ''}#refill:${o.slot}`,
    });
    slot.refills.push({ slot: o.slot, contact: r.contact, at: NOW, price: o.price });
    if (moveId && S.appts[moveId] && !S.appts[moveId].cancelled) {
      // Moved up: the later appointment is given back, and offered in turn.
      cancel(S.appts[moveId], 'moved up to an earlier slot', false);
    }
    return;
  }

  if (ctx.kind === 'recall') {
    const v = { ...vars, service: ctx.recall.service || 'appointment' };
    if (intent === 'no') {
      emit('recall_declined', { client: ctx.recall.ref, contact: r.contact, channel: r.channel,
        service: ctx.recall.service });
      return;
    }
    if (intent === 'yes') {
      emit('message', { contact: r.contact, channel: r.channel, client: ctx.recall.ref, detail: 'recall yes' },
        replyTo(r, 'recall_yes', v));
      return forward(r, `Would like to book their ${v.service}. They have the booking link too.`);
    }
    return forward(r, `Replied to the ${v.service} recall.`);
  }

  // A text out of the blue is only visible here. An email is already in the
  // front desk's inbox, and a second copy of it is noise.
  if (r.channel === 'sms') forward(r, 'Not a reply to anything open.');
});

return out;

// After the log: the calendar changes and the answers. One item can be both
// a booking to create and a text to send, and goes to both outputs.
return $('Apply the Reply').all()
  .map((i) => i.json)
  .filter((r) => r.action || (r.send_to && r.send_text))
  .map((r) => ({ json: {
    action: r.action || '', event_id: r.event_id || '',
    cal_summary: r.cal_summary || '', cal_start: r.cal_start || '', cal_end: r.cal_end || '',
    cal_description: r.cal_description || '',
    channel: r.send_to ? r.send_channel : '', to: r.send_to || '', subject: r.send_subject || '',
    text: r.send_text || '',
  } }));

parameters.message:
=A run of the no-show workflow stopped with an error.

Error:     {{ $json.execution.error.message }}
At node:   {{ $json.execution.lastNodeExecuted }}
Execution: {{ $json.execution.url }}

Decisions are logged before messages are sent, so running it again sends nothing twice. If it stopped after a waitlist booking, the next run tells the front desk whether the calendar event is missing.
